(()=>{'use strict';const A=App,E=Engine,C=Charts;const t=(a,b)=>A.t(a,b),e=v=>A.e(v),b=(...x)=>A.btn(...x),m=(v,c)=>A.money(v,c),ic=n=>A.icon(n),badge=(...x)=>A.badge(...x),p=()=>A.p;const context=()=>`${e(p().name)} · ${e(p().currency)} · ${p().quotes.length} ${t('supplier quotations','份供应商报价')}${p().sample?' · '+t('Fictional sample','虚构示例'):''}`;const metric=(label,value,note,icon)=>`<div class="metric">${ic(icon)}<div><div class="label">${label}</div><strong>${value}</strong><small>${note}</small></div></div>`;
function landing(){const s=E.sampleProject(),a=E.analyze(s);return `<div class="landing"><header class="landing-nav"><div class="brand"><span class="brand-mark">Q</span>QuotePilot</div><div class="landing-links"><a href="#how-it-works" data-action="how">${t('How it works','使用流程')}</a>${b('nav-projects',t('Your workspace','您的工作区'))}</div>${A.langButtons()}</header><section class="landing-hero"><h1>${t('Better buying.<br>Clearly.','更好采购。<br>清晰决策。')}</h1><p>${t('Turn supplier quotations into a purchasing decision you can explain.','将供应商报价转化为有据可查的采购决策。')}</p><div class="actions">${b('nav-projects',t('Open your workspace','进入工作区'),'','primary')}${b('explore-sample',t('Explore the sample','体验示例'),'arrow','ghost')}</div></section><section class="landing-preview" aria-label="${t('Fictional sample comparison','虚构示例比较')}"><div class="browser-dots"><i></i><i></i><i></i></div><div class="sample-content"><h2 class="sample-heading">${t('Office essentials','办公用品采购')}<small>${t('Fictional sample project','虚构示例项目')}</small></h2><div class="sample-quotes">${a.rows.map(r=>`<div class="sample-quote ${r.q.id===a.best?.q.id?'featured':''}"><h3>${e(r.q.name)}</h3><strong>${m(r.total,s.currency)}</strong><small>${A.days(r.q.days)}</small></div>`).join('')}</div>${[[t('Items after discount','折后商品'),'net'],[t('Shipping','运费'),'shippingAmount'],[t('Tax','税额'),'taxAmount'],[t('Total','合计'),'total']].map(([label,f])=>`<div class="sample-rows ${f==='total'?'total':''}"><span>${label}</span>${a.rows.map(r=>`<span>${m(r[f],s.currency)}</span>`).join('')}</div>`).join('')}</div><div class="preview-footer">${ic('shield')}${t('Verified calculations. Your priorities.','核实计算，按您的优先级决策。')}</div></section><section class="landing-workflow" id="how-it-works"><div><h2>${t('From scattered quotes<br>to a clear next step.','从分散的报价<br>到清晰的下一步。')}</h2><div>${[[t('Define your purchase','定义采购'),t('Set quantities, budget and delivery needs.','设置采购数量、预算与交付要求。')],[t('Compare the complete cost','比较完整成本'),t('Review freight, discounts and tax.','审核运费、折扣及税额。')],[t('Decide with evidence','依据证据决策'),t('Explore trade-offs and export your decision.','探索方案取舍，并导出采购决策。')]].map(([h,sub],i)=>`<div class="landing-step"><span>0${i+1}</span><div><h3>${h}</h3><p>${sub}</p></div></div>`).join('')}</div></div></section><section class="landing-privacy"><h2>${t('Your data. Your decision.','您的数据，您的决策。')}</h2><p>${t('Core analysis stays in your browser. Connect an AI model only when you choose.','核心分析在浏览器内完成，仅在您选择时连接 AI 模型。')}</p>${b('project-new',t('Start a project','开始项目'))}</section><footer class="landing-footer">QuotePilot 2.1 · ${t('Built for thoughtful purchasing.','让每次采购都有据可依。')}</footer></div>`;}
function stage(project){if(project.archived)return t('Archived','已归档');if(project.decision)return project.decision.fingerprint===E.fingerprint(project)?t('Decision recorded','已记录决策'):t('Decision needs review','决策需复核');if(!project.quotes.length)return t('Define purchase','定义采购');if(E.analyze(project).best)return t('Ready to decide','可决策');return t('Collect & review','收集与审核');}
function projects(){const projects=A.workspace.projects,active=projects.filter(x=>!x.archived),shown=projects.filter(x=>(A.projectFilter==='all'||(A.projectFilter==='archived'?x.archived:!x.archived))&&x.name.toLowerCase().includes(A.projectSearch.toLowerCase()));return A.heading(t('Your purchasing workspace','您的采购工作区'),t('Keep every purchase, quotation and decision in one place.','将每项采购、报价及决策保存在同一工作区。'),b('backup',t('Back up workspace','备份工作区'),'download')+b('project-new',t('Create project','创建项目'),'plus','primary'))+`<div class="metrics">${metric(t('Active projects','进行中项目'),active.length,t('Separate baskets and currencies','独立清单与币种'),'projects')}${metric(t('Supplier quotations','供应商报价'),active.reduce((s,x)=>s+x.quotes.length,0),t('Across active projects','进行中项目合计'),'quote')}${metric(t('Ready to decide','可以决策'),active.filter(x=>E.analyze(x).best&&!x.decision).length,t('At least one eligible option','至少一份合格报价'),'check')}${metric(t('Recorded decisions','已记录决策'),projects.filter(x=>x.decision).length,t('With a dated evidence snapshot','包含带日期的依据快照'),'layers')}</div><div class="panel"><div class="toolbar"><div class="filters"><input id="project-search" placeholder="${t('Search projects…','搜索项目…')}" aria-label="${t('Search projects','搜索项目')}" value="${e(A.projectSearch)}"><select id="project-filter" aria-label="${t('Project status','项目状态')}">${[['active',t('Active projects','进行中')],['archived',t('Archived','已归档')],['all',t('All projects','全部项目')]].map(([v,l])=>`<option value="${v}" ${A.projectFilter===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="actions">${b('restore',t('Restore backup','恢复备份'),'upload','small')}${b('sample',t('Add sample','添加示例'),'quote','small')}</div></div>${shown.length?`<div class="table-wrap"><table class="project-table"><thead><tr>${[t('Project','项目'),t('Status','状态'),t('Budget','预算'),t('Quotes','报价'),t('Updated','更新时间'),t('Actions','操作')].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${shown.map(x=>`<tr><td><div class="project-name"><span class="project-icon">${ic('projects')}</span><div><strong>${e(x.name)}</strong><small>${x.basket.length} ${t('products','种产品')} · ${e(x.currency)}${x.sample?' · '+t('Sample','示例'):''}</small></div></div></td><td>${badge(stage(x),x.archived?'':x.decision?'blue':'')}</td><td>${E.blank(x.budget)?'—':m(x.budget,x.currency)}</td><td>${x.quotes.length}</td><td class="small-text">${e(new Date(x.updatedAt).toLocaleDateString(A.lang==='zh'?'zh-CN':'en-US'))}</td><td><div class="actions">${b('project-open',t('Open','打开'),'arrow','small',`data-id="${e(x.id)}"`)}${b('project-copy',t('Duplicate','复制'),'','small',`data-id="${e(x.id)}"`)}${b(x.archived?'project-restore':'project-archive',x.archived?t('Restore','恢复'):t('Archive','归档'),'archive','small',`data-id="${e(x.id)}"`)}</div></td></tr>`).join('')}</tbody></table></div>`:A.empty()}</div><p class="footnote">${t('Projects are stored on this device. Back up before clearing browser data or moving to another browser. Restoring a v1 backup creates a v2 project with quotations marked for review.','项目保存在本设备。清除浏览器数据或迁移前请备份。恢复 v1 备份会创建 v2 项目，并将报价标记为待审核。')}</p>`;}
function quotes(){if(!p())return A.empty();const a=E.analyze(p());return A.heading(t('Bring every offer into focus.','让每份报价都清晰可见。'),context(),b('project-edit',t('Edit purchase','编辑采购'),'edit')+b('quote-new',t('Add quotation','添加报价'),'plus','primary'))+A.workflow(1)+`<div class="dropzone" id="drop-zone"><div class="drop-copy">${ic('upload')}<div><h3>${t('Import supplier quotations','导入供应商报价')}</h3><p>${t('Excel or CSV · review columns and terms before saving · up to 10 MB','Excel 或 CSV · 保存前审核字段与条款 · 最大 10 MB')}</p></div></div><div class="actions">${b('template',t('Download template','下载模板'),'download','small')}${b('import',t('Choose file','选择文件'),'upload')}</div></div><div class="panel"><div class="toolbar"><h2>${t('Supplier quotations','供应商报价')} <span class="muted small-text">${p().quotes.length}</span></h2><div class="actions"><input id="supplier-search" placeholder="${t('Search suppliers…','搜索供应商…')}" aria-label="${t('Search suppliers','搜索供应商')}" style="width:190px">${b('nav-analysis',t('Open analysis','打开分析'),'arrow','small')}</div></div>${a.rows.length?`<div class="table-wrap"><table style="min-width:850px"><thead><tr>${[t('Supplier / quote','供应商 / 报价'),t('Coverage','覆盖'),t('Landed cost','到手成本'),t('Delivery','交货期'),t('Readiness','准备状态'),t('Actions','操作')].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${a.rows.map(r=>`<tr data-supplier="${e(r.q.name.toLowerCase())}"><td><strong>${e(r.q.name)}</strong><small>${e(r.q.reference||r.q.source)} · ${e(r.q.currency)}${r.q.taxIncluded?' · '+t('Tax-inclusive prices','含税单价'):''}</small></td><td>${p().basket.filter(x=>r.q.items.some(y=>E.matches(y,x))).length}/${p().basket.length}</td><td><strong>${m(r.total,r.q.currency)}</strong><small>${r.q.tax}% ${t('tax rate','税率')}</small></td><td>${A.days(r.q.days)}</td><td>${badge(r.reasons.length?t('Needs attention','需要检查'):t('Eligible','合格'),r.reasons.length?'orange':'blue')}<small>${r.reasons.slice(0,2).map(A.reason).map(e).join(' · ')}</small></td><td><div class="actions">${b('quote-edit',t('Review','审核'),'edit','small',`data-id="${e(r.q.id)}"`)}${b('quote-copy',t('Copy','复制'),'','small',`data-id="${e(r.q.id)}"`)}${b('quote-delete','','trash','small danger',`data-id="${e(r.q.id)}" aria-label="${t('Delete','删除')} ${e(r.q.name)}"`)}</div></td></tr>`).join('')}</tbody></table></div><p id="supplier-no-results" class="footnote" hidden>${t('No matching suppliers.','没有匹配的供应商。')}</p>`:`<div class="empty"><h2>${t('Add your first quotation','添加第一份报价')}</h2><p>${t('Import a file or enter the supplier’s terms manually. You review the data before it can enter the ranking.','导入文件或手动填写供应商条款。审核确认后，该报价才可参与排名。')}</p>${b('import',t('Import quotation','导入报价'),'upload','primary')}</div>`}</div><div class="notice info">${t('Compare like for like: purchasing SKUs, specifications, units and quantities must match. Names are used only when both SKUs are blank. Review freight, tax, validity and minimum orders; imported quotes start as unreviewed.','同等条件比较：采购SKU、规格、单位及数量必须一致；双方SKU都为空时才使用名称。请核对运费、税率、有效期与起订条件；导入报价默认尚未审核。')}</div>`;}
function lens(a){return `<section class="panel decision-lens"><div class="panel-head"><div><h2>${t('Decision lens','决策视角')}</h2><p>${t('Set the trade-offs that matter to this purchase.','设置本次采购的优先考虑因素。')}</p></div>${ic('settings')}</div><form id="weights-form">${[['cost',t('Cost priority','成本权重')],['delivery',t('Delivery priority','交期权重')],['reliability',t('Reliability priority','可靠性权重')]].map(([k,l])=>`<div class="weight-row"><div class="weight-label"><label for="weight-${k}">${l}</label><b data-weight-value="${k}">${p().weights[k]}</b></div><input id="weight-${k}" name="${k}" type="range" min="0" max="100" step="5" value="${p().weights[k]}" data-weight="${k}" aria-label="${l}"></div>`).join('')}<div class="lens-fields">${A.field('deadline',t('Required within (days)','最迟交期（天）'),p().deadline,'number','min="0" max="3650" step="0.1" placeholder="'+t('Optional','可选')+'"')}${A.field('targetDays',t('Full-score delivery','满分交期'),p().targetDays,'number','required min="0" max="3649" step="0.1"')}${A.field('limitDays',t('Zero-score delivery','零分交期'),p().limitDays,'number','required min="0.1" max="3650" step="0.1"')}</div><div class="form-error" id="weights-error" role="alert"></div><button class="primary" type="submit">${t('Apply priorities','应用优先级')}</button></form><div class="notice info small-text">${t('Missing evidence stays unknown. A quote is excluded if it lacks data needed by an active priority.','缺失依据保持未知。报价缺少启用指标所需数据时，不参与排名。')}</div>${a.best?`<div class="recommendation"><small>${a.ties.length>1?t('Joint leading score','并列领先得分'):t('Recommended supplier','推荐供应商')}</small><h3>${e(a.best.q.name)}</h3>${a.ties.length>1?`<p>${a.ties.map(r=>e(r.q.name)).join(' · ')}</p>`:''}<p><strong>${m(a.best.total)}</strong> · ${A.days(a.best.q.days)} · ${a.best.score.toFixed(1)}/100</p><p>${t('Effective weights','实际权重')}: ${Object.values(a.weights).map(v=>Math.round(v*100)+'%').join(' / ')}</p>${b('nav-advisor',t('Review evidence & actions','查看依据与行动'),'arrow','ghost small')}</div>`:`<div class="notice">${t('No eligible recommendation. Check required data, constraints and nonzero priorities.','暂无合格推荐，请检查数据、约束及非零权重。')}</div>`}</section>`;}
function ranking(a){return `<div class="panel"><div class="panel-head"><h2>${t('The shortlist','候选供应商')}</h2><span class="muted small-text">${t('Select a supplier to inspect the evidence','选择供应商查看依据')}</span></div><div class="table-wrap"><table style="min-width:700px"><thead><tr>${[t('Supplier','供应商'),t('Landed cost','到手成本'),t('Quoted delivery','报价交期'),t('Weighted score','加权得分'),t('Status','状态'),t('Details','详情')].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${a.rows.map(r=>`<tr><td><strong>${e(r.q.name)}</strong></td><td>${m(r.total,r.q.currency)}</td><td>${A.days(r.q.days)}</td><td>${r.score===null?'—':r.score.toFixed(1)}</td><td>${badge(r.reasons.length?t('Excluded','不参与'):t('Eligible','合格'),r.reasons.length?'orange':'blue')}</td><td>${b('inspect',t('Inspect','查看'),'arrow','small',`data-id="${e(r.q.id)}"`)}</td></tr>`).join('')}</tbody></table></div></div>`;}
function overview(a){return `<div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><div><h2>${t('The full cost, side by side','完整成本，并排比较')}</h2><p>${t('Landed cost from verified quote terms. Select a bar to inspect.','按已审核条款计算到手成本，选择柱条查看明细。')}</p></div>${badge(p().currency)}</div>${C.cost(a.eligible,{money:m,t,selected:A.selectedSupplier})}<div class="savings-note"><span>${t('Eligible quote spread','可比报价差额')} <b>${m(a.spread)}</b></span>${a.baselineSavings!==null?`<span>${t('Baseline less recommended cost','基准减推荐成本')} <b>${m(a.baselineSavings)}</b></span>`:''}<small>${t('Potential differences only. Not realized savings.','仅为潜在差额，并非已实现节省。')}</small></div></section><div class="chart-pair"><section class="panel"><h2>${t('Cost versus quoted delivery','成本与报价交期')}</h2><p>${t('Lower cost and shorter delivery sit toward the lower left.','成本越低、交期越短，越靠近左下角。')}</p>${C.scatter(a.eligible,{money:m,t})}</section><section class="panel"><h2>${t('When priorities change','当优先级改变时')}</h2><p>${t('Sensitivity of score to cost priority. Explore in Scenarios.','成本权重变化对得分的影响，可在“情景”中探索。')}</p>${C.sensitivity(a.rows,E.sensitivity(p()),{t,current:a.weights.cost*100})}</section></div></div>${lens(a)}</div>${ranking(a)}`;}
function matrix(a){const rows=[[t('Item subtotal (quoted basis)','商品小计（报价口径）'),r=>m(r.subtotal,r.q.currency)],[t('Discount','折扣'),r=>'−'+m(r.discountAmount,r.q.currency)],[t('Shipping','运费'),r=>m(r.shippingAmount,r.q.currency)],[t('Other fees','其他费用'),r=>m(r.feesAmount,r.q.currency)],[t('Tax','税额'),r=>m(r.taxAmount,r.q.currency)],[t('Total landed cost','到手总成本'),r=>m(r.total,r.q.currency),'total-row'],[t('Quoted delivery','报价交期'),r=>A.days(r.q.days)],[t('Payment exposure','预付款金额'),r=>m(r.prepayment,r.q.currency)],[t('Reliability evidence','可靠性依据'),r=>r.reliability?`${r.reliability.value.toFixed(1)}/100 · ${r.reliability.kind==='observed'?t('Observed','有历史记录'):t('User scored','用户评分')}`:t('Unknown','未知')],[t('Eligibility','资格'),r=>r.reasons.length?r.reasons.map(A.reason).map(e).join('<br>'):badge(t('Eligible','合格'),'blue')]];return `<section class="panel"><div class="panel-head"><div><h2>${t('Compare equivalent offers','比较同等条件的报价')}</h2><p>${t('Quantities, units and tax basis remain visible. Different currencies are never converted automatically.','数量、单位及含税口径清晰显示；不同币种不会自动换算。')}</p></div>${b('project-edit',t('Edit basket','编辑清单'),'edit','small')}</div><div class="table-wrap"><table class="matrix" style="min-width:${Math.max(730,240+a.rows.length*205)}px"><thead><tr><th>${t('Purchase requirements','采购需求')}</th>${a.rows.map(r=>`<th class="${r.q.id===a.best?.q.id?'top-choice':''}"><div class="supplier-head">${e(r.q.name)}<span class="line-unit">${e(r.q.currency)} · ${r.q.taxIncluded?t('Tax-inclusive item prices','含税商品单价'):t('Tax-exclusive item prices','税前商品单价')}</span>${r.q.id===a.best?.q.id?badge(t('Leading score','得分领先'),'blue'):''}</div></th>`).join('')}</tr></thead><tbody>${p().basket.map(x=>`<tr><th>${e(E.itemLabel(x))}<span class="line-unit">${e(x.qty)} ${e(x.unit)}</span></th>${a.rows.map(r=>{const line=r.q.items.find(i=>E.matches(i,x));return `<td>${line?`${(A.unitMoney||m)(line.price,r.q.currency)}<span class="line-unit">× ${e(line.qty)} ${e(line.unit)}</span>`:'—'}</td>`;}).join('')}</tr>`).join('')}${rows.map(([l,fn,cls])=>`<tr class="${cls||''}"><th>${l}</th>${a.rows.map(r=>`<td>${fn(r)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
function scenarios(a){const cost=A.scenarioCost??Math.round(a.weights.cost*100),other=Number(p().weights.delivery)+Number(p().weights.reliability),delivery=other?(100-cost)*Number(p().weights.delivery)/other:100-cost,rel=100-cost-delivery,sa=E.analyze(p(),{cost,delivery,reliability:rel}),allocation=A.allocation||E.cheapestLines(p()),split=E.split(p(),allocation);return `<div class="panel"><div class="panel-head"><div><h2>${t('Explore the decision before committing','承诺采购前探索不同选择')}</h2><p>${t('Scenario changes are temporary until you apply them.','情景调整在应用前不会更改项目设置。')}</p></div></div><div class="preset-group">${[[90,t('Cost first','成本优先')],[70,t('Balanced','均衡')],[20,t('Time first','时间优先')]].map(([v,l])=>b('scenario-preset',l,'',cost===v?'selected':'',`data-value="${v}"`)).join('')}</div><div class="split-grid"><div><div class="weight-label"><label for="scenario-cost">${t('Cost priority','成本权重')}</label><b id="scenario-value">${cost}%</b></div><input id="scenario-cost" type="range" min="0" max="100" step="5" value="${cost}" aria-label="${t('Scenario cost priority','情景成本权重')}"><p class="footnote">${t('The remaining weight keeps the current delivery/reliability ratio; if both are zero, it goes to delivery.','剩余权重保持当前交期/可靠性比例；如果二者均为零，则全部分配给交期。')}</p>${C.sensitivity(a.rows,E.sensitivity(p()),{t,current:cost})}</div><div class="split-result"><span class="muted small-text">${t('Scenario leader','情景领先供应商')}</span><h2>${sa.best?e(sa.best.q.name):t('No eligible option','没有合格方案')}</h2><strong>${sa.best?m(sa.best.total):'—'}</strong><p>${sa.best?`${A.days(sa.best.q.days)} · ${sa.best.score.toFixed(1)}/100`:t('Check missing criteria and constraints.','请检查缺失数据与限制条件。')}</p><p class="footnote">${t('This result uses the same quote calculations and eligibility rules as the live dashboard.','本结果与实际分析界面使用相同的成本及资格规则。')}</p>${b('scenario-apply',t('Apply these priorities','应用这些优先级'),'check','primary')}</div></div></div><section class="panel"><div class="panel-head"><div><h2>${t('Split the purchase, see the real trade-off','拆分采购，查看真实取舍')}</h2><p>${t('Assign each whole product line to a supplier. Shipping and fees are charged once per selected supplier.','将每项产品的完整数量分配给供应商，每家所选供应商的运费及费用各计一次。')}</p></div>${b('split-cheapest',t('Suggest lowest unit prices','按最低单价分配'),'settings','small')}</div><div class="split-grid"><div>${p().basket.map(x=>`<label style="margin-bottom:13px">${e(E.itemLabel(x))} · ${e(x.qty)} ${e(x.unit)}<select data-allocation="${e(E.itemKey(x))}" aria-label="${e(E.itemLabel(x))} ${t('supplier','供应商')}"><option value="">${t('Choose supplier','选择供应商')}</option>${p().quotes.filter(q=>q.items.some(i=>E.matches(i,x))).map(q=>`<option value="${e(q.id)}" ${allocation[E.itemKey(x)]===q.id?'selected':''}>${e(q.name)}</option>`).join('')}</select></label>`).join('')}</div><div class="split-result"><span class="muted small-text">${t('Split-order scenario','拆单情景')}</span><strong>${m(split.total)}</strong><p>${split.suppliers.length} ${t('suppliers','家供应商')} · ${A.days(split.days)}</p>${split.issues.length?`<div class="notice">${t('Not ready to purchase:','尚不满足采购条件：')} ${split.issues.map(A.reason).map(e).join(' · ')}</div>`:`<div class="notice info">${t('Supported by the entered terms. Confirm supplier acceptance before ordering.','输入条款支持此方案，下单前仍需确认供应商接受。')}</div>`}<p class="footnote">${t('Lowest unit-price allocation is a starting point, not an optimization guarantee. Fixed discounts are removed from partial orders unless the whole quote is selected.','逐项最低价仅为起点，不保证总成本最优。仅选择部分商品时，固定金额折扣不予计入。')}</p>${split.suppliers.map(r=>`<p class="small-text">${e(r.q.name)}: ${m(r.total,r.q.currency)}</p>`).join('')}</div></div></section>`;}
function evidence(a){return `<div class="chart-pair"><section class="panel"><h2>${t('Observed delivery performance','已观测的交付表现')}</h2><p class="footnote">${t('Only entered historical order counts appear here. Quoted lead times are not historical performance.','此处仅显示用户输入的历史订单记录。报价交期并非历史履约表现。')}</p>${C.history(a.rows,{t})}${a.rows.filter(r=>r.reliability?.kind==='observed').map(r=>`<p class="footnote">${e(r.q.name)}: ${e(r.q.historySource)}</p>`).join('')}</section><section class="panel"><h2>${t('How the score works','评分方法')}</h2><div class="formula">${t('Cost = lowest eligible cost ÷ supplier cost × 100\nDelivery = 100 at or before the target; declines linearly to 0 at the zero-score day\nReliability = supplied score or observed on-time rate\nFinal = normalized weighted average','成本 = 最低合格成本 ÷ 供应商成本 × 100\n交期 = 目标天数以内100分，随后线性降至零分天数时的0分\n可靠性 = 用户提供分数或历史准时率\n总分 = 归一化权重的加权平均')}</div><p class="footnote">${t('A small price gap stays a small score gap. Unknown data required by active criteria excludes that quote. Equal scores use cost then supplier name for display; all tied leaders are reported. Scores support a decision, not a guarantee.','较小价差仅产生较小得分差异。缺少启用指标所需数据的报价不参与排名。并列得分按成本、再按名称显示；所有并列领先者均列出。得分用于辅助决策，不构成保证。')}</p></section></div><section class="panel"><h2>${t('Cost and eligibility rules','成本与资格规则')}</h2><p class="footnote">${t('Line subtotals, discounts and taxes use exact decimal half-up rounding at the currency’s minor unit. Tax-inclusive items extract their embedded tax; freight and other fees are entered before tax. Minimum order value is checked against discounted items excluding tax.','行小计、折扣及税额使用精确十进制计算，按币种最小单位四舍五入。含税商品提取内含税额；运费及其他费用均按税前金额输入。起订金额以折后税前商品金额核对。')}</p><div class="table-wrap"><table><thead><tr><th>${t('Supplier','供应商')}</th><th>${t('Quoted source','报价来源')}</th><th>${t('Reliability source','可靠性来源')}</th><th>${t('Eligibility','资格')}</th></tr></thead><tbody>${a.rows.map(r=>`<tr><td>${e(r.q.name)}</td><td>${e(r.q.source)}</td><td>${e(r.reliability?.source||t('Not provided','未提供'))}</td><td>${r.reasons.length?r.reasons.map(A.reason).map(e).join('; '):t('Eligible','合格')}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>${t('Project activity','项目活动记录')}</h2>${(p().activity||[]).slice(0,15).map(x=>`<div class="activity">${e(x.action)}<small>${e(new Date(x.at).toLocaleString())}</small></div>`).join('')||`<p class="footnote">${t('Changes to this project will appear here. This is a local activity log, not a tamper-proof compliance audit.','本项目的更改会显示在此处。这是本地活动记录，并非不可篡改的合规审计。')}</p>`}</section>`;}
function analysis(){if(!p())return A.empty();const a=E.analyze(p());let html=A.heading(t('Make the right buying decision.','做出合适的采购决策。'),context(),b('export',t('Export','导出'),'download')+b('nav-advisor',t('Review decision','审核决策'),'arrow','primary'))+A.workflow(2);if(!p().quotes.length)return html+A.empty();const known=a.eligible.filter(r=>!E.blank(r.q.days));html+=`<div class="metrics">${metric(t('Best eligible cost','最低合格成本'),a.cheapest?m(a.cheapest.total):'—',t('Like-for-like eligible quotations','同等条件的合格报价'),'cost')}${metric(t('Budget headroom','预算余量'),a.headroom===null?'—':m(a.headroom),t('Against the recommended option','相对推荐方案'),'budget')}${metric(t('Fastest quoted delivery','最快报价交期'),known.length?A.days(Math.min(...known.map(r=>Number(r.q.days)))):'—',t('Quoted, not observed performance','报价交期，并非历史表现'),'truck')}${metric(t('Data readiness','数据准备情况'),`${a.eligible.length} / ${a.rows.length}`,t('Eligible under current priorities','当前优先级下符合条件'),'layers')}</div>`;if(a.rows.some(r=>r.reasons.length))html+=`<div class="notice">${a.rows.filter(r=>r.reasons.length).map(r=>`<b>${e(r.q.name)}</b>: ${r.reasons.map(A.reason).map(e).join(', ')}`).join(' · ')}</div>`;if(a.eligible.length===1)html+=`<div class="notice info">${t('Only one eligible quote. This is a single-option assessment, not a competitive conclusion.','仅有一份合格报价。这是单一方案评估，并非竞争性结论。')}</div>`;html+=`<div class="tabs" role="tablist">${[['overview',t('Overview','概览')],['matrix',t('Quote matrix','报价矩阵')],['scenarios',t('Scenarios','情景')],['evidence',t('Evidence','依据')]].map(([k,l])=>b('tab-'+k,l,'',A.analysisTab===k?'active':'',`role="tab" aria-selected="${A.analysisTab===k}"`)).join('')}</div>${({overview,matrix,scenarios,evidence})[A.analysisTab](a)}`;return html;}
function advisor(){if(!p())return A.empty();const report=Analyst.report(p(),A.lang),a=report.analysis,bundle=report.bundle,saved=p().aiReport,stale=saved&&!report.active,activeBundle=bundle,actions=report.actions,chosen=report.chosen;return A.heading(t('A clear recommendation. A practical next step.','清晰的推荐，实用的下一步。'),t('Verified calculations first. Optional AI to prioritize the opportunities.','先核实计算，再选择是否由 AI 帮助排列建议优先级。'),b('export',t('Export decision pack','导出决策包'),'download')+b('decision',t('Record decision','记录决策'),'check','primary'))+A.workflow(3)+(p().decision?`<div class="notice ${p().decision.fingerprint===E.fingerprint(p())?'info':''}"><b>${t('Recorded decision','已记录决策')}: ${e(p().decision.supplierName)}</b> · ${m(p().decision.total,p().decision.currency)} · ${e(new Date(p().decision.at).toLocaleDateString())}<br>${p().decision.fingerprint===E.fingerprint(p())?t('This record matches the current data.','记录与当前数据一致。'):t('Project data or date has changed. Review before relying on this saved decision.','项目数据或日期已变更，使用此记录前请重新审核。')}</div>`:'')+`<div class="report-grid"><div><section class="report-hero"><span class="small-text">${saved&&!stale?t('AI-prioritized · evidence checked','AI 排序 · 依据已校验'):t('Local procurement brief · no API needed','本地采购简报 · 无需 API')}</span>${saved&&!stale&&saved.at?`<p class="footnote">${e(saved.model)} · ${e(new Date(saved.at).toLocaleString())}</p>`:''}<h2>${chosen?e(chosen.q.name):t('Complete the evidence first','请先补齐依据')}</h2><p>${chosen?e(t(`${chosen.q.name} is eligible under the current constraints. Review the cost, delivery and evidence trade-offs below before choosing.`,`${chosen.q.name} 符合当前约束条件。选择前请查看以下成本、交期及依据的取舍。`)):t('Resolve quotation review, basket differences or missing required evidence to get a supported recommendation.','请解决报价审核、清单差异或所需依据缺失后再获取推荐。')}</p>${chosen?`<div class="fact-grid"><div class="fact"><small>${t('Landed cost','到手成本')}</small><strong>${m(chosen.total)}</strong></div><div class="fact"><small>${t('Quoted delivery','报价交期')}</small><strong>${A.days(chosen.q.days)}</strong></div><div class="fact"><small>${t('Weighted score','加权得分')}</small><strong>${chosen.score?.toFixed(1)??'—'} / 100</strong></div><div class="fact"><small>${t('Quote spread','可比报价差额')}</small><strong>${m(a.spread)}</strong></div></div>`:''}${saved&&!stale?`<div style="margin-top:14px">${saved.result.reasonFactIds.map(id=>`<button type="button" class="evidence-link" data-action="fact" data-fact="${e(id)}">${e(bundle.facts.find(f=>f.id===id)?.label||id)} ${ic('arrow')}</button>`).join('')}</div>`:''}</section>${saved&&stale?`<div class="notice">${t('The saved AI report is stale. Current local advice is shown below; generate again for an updated AI report.','已保存的 AI 报告已过时。下方显示当前本地建议，请重新生成AI报告。')}</div>`:''}${saved&&!stale&&chosen?.q.id!==a.best?.q.id?`<div class="notice info">${t('AI selected an eligible alternative to the weighted leader. Inspect its lower score or higher cost before choosing it.','AI 选择了合格的替代方案，而非加权得分最高者。请检查得分或成本差异后再决定。')}</div>`:''}<section class="panel"><div class="panel-head"><div><h2>${t('Your purchasing action plan','采购行动计划')}</h2><p>${t('Every recommendation links to the data that supports it.','每条建议均链接到支持它的数据。')}</p></div>${saved?b('clear-ai',t('Use local brief','使用本地简报'),'','small'):''}</div>${actions.length?actions.map(o=>`<article class="report-card"><span class="badge">${({selection:t('Supplier selection','供应商选择'),risk:t('Risk & evidence','风险与依据'),cost:t('Cost opportunity','成本机会'),negotiation:t('Negotiation','协商'),alternative:t('Alternative strategy','替代策略'),next:t('Next step','下一步')})[o.section]}</span><h3 style="margin-top:9px">${e(o.title)}</h3><p>${e(o.body)}</p><div>${o.factIds.map(id=>`<button type="button" class="evidence-link" data-action="fact" data-fact="${e(id)}" data-old="no">${e(activeBundle.facts.find(f=>f.id===id)?.label||id)} ${ic('arrow')}</button>`).join('')}</div></article>`).join(''):`<p class="footnote">${t('Add and review quotations to build a useful purchasing brief.','添加并审核报价后，即可生成有用的采购简报。')}</p>`}</section></div><div><section class="panel"><div class="panel-head"><div><h2>${t('Procurement Analyst','采购分析师')}</h2><p>${t('Optional connected AI','可选的联网 AI')}</p></div>${ic('spark')}</div><p class="small-text">${t('The model selects supported opportunities and cites verified facts. It cannot insert new financial figures or supplier ratings into this report.','模型仅选择有依据的机会并引用已核实事实，无法在报告中插入新的财务数字或供应商评级。')}</p><label style="margin:18px 0">${t('What should the analyst focus on?','希望分析师重点关注什么？')}<textarea id="ai-focus" rows="3" maxlength="1000" placeholder="${t('For example: reduce deposit exposure without missing the delivery date.','例如：在不影响交货时间的情况下降低预付款风险。')}"></textarea></label>${A.aiBusy?`<div class="pending-indicator"><i class="spinner"></i>${t('Analyzing verified evidence…','正在分析已核实的依据…')}</div>${b('ai-cancel',t('Cancel request','取消请求'),'close','small')}`:b('ai-preview',t('Preview data & generate','预览数据并生成'),'spark','primary')}<div class="notice info">${t('Generation sends the previewed snapshot to your configured endpoint and may incur provider charges. API keys stay in memory and are never included in backups.','生成时会将预览快照发送到配置的接口，服务商可能收费。API 密钥仅在内存中保留，不包含在备份里。')}</div>${b('nav-settings',t('Configure model connection','配置模型连接'),'settings','ghost small')}<p class="footnote">${t('Core calculations, local advice and exports work without an API.','核心计算、本地建议及导出无需 API。')}</p></section><section class="panel"><h3>${t('Decision checklist','决策检查清单')}</h3><p class="footnote">${t('1. Match products, units and quantities.\n2. Confirm freight, taxes and validity.\n3. Review delivery and payment commitments.\n4. Confirm any partial-order terms.\n5. Record your reason and export the decision.','1. 匹配产品、单位及数量。\n2. 确认运费、税率及有效期。\n3. 审核交期与付款承诺。\n4. 确认拆单条款。\n5. 记录理由并导出决策。').replaceAll('\n','<br>')}</p></section></div></div>`;}
function settings(){const cfg=A.workspace.api;return A.heading(t('Settings & connections','设置与连接'),t('Choose how QuotePilot works for your business.','按您的业务需求配置 QuotePilot。'))+`<div class="settings-grid"><div><section class="panel"><div class="panel-head"><div><h2>${t('AI model connection','AI 模型连接')}</h2><p>${t('Use an endpoint compatible with Chat Completions or Responses.','使用兼容 Chat Completions 或 Responses 的接口。')}</p></div>${ic('link')}</div><form id="api-form"><div class="fields two"><label class="full">${t('Complete API endpoint URL','完整 API 接口地址')}<input name="endpoint" type="url" required value="${e(cfg.endpoint)}" maxlength="2000" placeholder="https://provider.example/v1/chat/completions"><small>${t('HTTPS required, except localhost models. No automatic endpoint rewriting.','必须使用 HTTPS，本地模型除外；不会自动改写地址。')}</small></label><label>${t('Protocol','协议')}<select name="protocol"><option value="chat" ${cfg.protocol==='chat'?'selected':''}>Chat Completions</option><option value="responses" ${cfg.protocol==='responses'?'selected':''}>Responses</option></select></label>${A.field('model',t('Model ID','模型 ID'),cfg.model,'text','required maxlength="200" placeholder="your-provider-model-id"')}<label class="full">${t('API key · memory only','API 密钥 · 仅存内存')}<input name="apiKey" type="password" autocomplete="off" spellcheck="false" placeholder="${A.apiKey?t('A key is in memory; leave blank to keep it','内存中已有密钥，留空保留'):t('Paste your provider key, or leave empty for a local endpoint','粘贴密钥，本地接口可留空')}" maxlength="2000"><small>${t('Reloading clears the key. Changing endpoints clears the old key unless you enter a new one.','刷新页面会清除密钥；更换接口时会清除旧密钥，除非您输入新密钥。')}</small></label>${A.field('timeout',t('Request timeout (seconds)','请求超时（秒）'),cfg.timeout,'number','required min="5" max="120" step="1"')}</div><div class="form-error" id="api-error" role="alert"></div><div class="actions"><button type="submit" class="primary">${t('Save connection','保存连接')}</button>${b('api-test',t('Test saved connection','测试已保存的连接'),'link')}${b('forget-key',t('Forget key','清除密钥'),'trash','small')}</div></form>${A.apiKey?`<p class="footnote">${t('Key is bound to','密钥绑定接口')}: ${e(A.keyEndpoint)}</p>`:''}${A.apiStatus?`<div class="notice info" id="api-status" role="status">${e(A.apiStatus)}</div>`:''}<p class="footnote">${t('Connection tests send a tiny JSON test prompt, no procurement data. They can still incur provider charges. Browser CORS must be enabled by your endpoint; QuotePilot does not route keys through a public proxy.','连接测试仅发送简短 JSON 测试提示，不含采购数据，但仍可能产生服务商费用。接口需支持浏览器 CORS；QuotePilot 不会通过公共代理转发密钥。')}</p></section><section class="panel"><h2>${t('Workspace & data','工作区与数据')}</h2><div class="fields two"><label>${t('Interface language','界面语言')}<select id="preference-language"><option value="en" ${A.lang==='en'?'selected':''}>English</option><option value="zh" ${A.lang==='zh'?'selected':''}>简体中文</option></select></label></div><div class="actions">${b('backup',t('Download backup','下载备份'),'download')}${b('restore',t('Restore v1 / v2 backup','恢复 v1 / v2 备份'),'upload')}</div><p class="footnote">${t('Backups include projects, quotations, recorded decisions and reports. They exclude API keys. Restoring replaces this v2 workspace after confirmation; the old v1 browser storage is retained.','备份包含项目、报价、决策及报告，不包含 API 密钥。确认恢复后会替换当前 v2 工作区；原 v1 浏览器存储仍保留。')}</p></section></div><div><section class="panel"><h2>${t('Privacy, in plain language','隐私说明')}</h2><p class="footnote">${t('Quotations and deterministic analysis stay in this browser. Only an explicit AI generation sends the previewed project snapshot to the endpoint you configure. Your provider governs its data handling. Memory-only keys are still accessible to this page and browser extensions. For production, use your own authenticated relay that holds provider keys on its server. Use only a trusted endpoint; never put keys in its URL.','报价与确定性分析保留在浏览器中。仅在明确生成 AI 报告时，才向您配置的接口发送已预览的项目快照。数据处理由该服务商负责。仅存内存的密钥仍可被本页面或浏览器扩展访问。正式使用建议采用您自行管理、带身份验证并在服务器保存密钥的代理。仅使用可信接口，切勿把密钥放入URL。')}</p></section><section class="panel"><h2>${t('Procurement Analyst Skill','采购分析师技能')}</h2><p class="footnote">${t('A constrained analytical workflow selects eligible suppliers and prioritizes evidence-backed negotiation, risk and purchasing actions. Financial values always come from the calculation engine.','受约束的分析流程选择合格供应商，并对有依据的协商、风险及采购行动排序。财务数值始终来自计算引擎。')}</p>${b('skill',t('Read analyst rules','查看分析师规则'),'quote','small')}</section><section class="panel"><h2>QuotePilot 2.1</h2><p class="footnote">${t('Browser-based, offline-capable procurement decision support. One local workspace; no implied team approval or purchase order submission.','支持离线的浏览器采购决策工具。单一本地工作区，不代表团队审批，也不会提交采购订单。')}</p><a href="README.md" target="_blank" class="small-text">${t('User guide & testing information','使用指南及测试信息')}</a></section></div></div>`;}
A.pages={landing,projects,quotes,analysis,advisor,settings};A.stage=stage;
})();
